INSERT INTO public.appointments (id, patient_id, schedule_id, service_id, price, status, cancel_reason, canceled_at, canceled_by, conclusion, created_at) OVERRIDING SYSTEM VALUE VALUES (56, 15, 9684, 8, 1500, 'completed', NULL, NULL, NULL, 'Папиллома кожи шеи (D23.4). Удалена под местной анестезией, материал направлен на гистологию. Обработка раны хлоргексидином 2 раза в день, снятие швов через 7 дней.', '2026-09-29 10:00:00+03');
